examples:
// Simple confirmation
<ConfirmationModal
  isOpen={isOpen}
  onClose={() => setIsOpen(false)}
  onConfirm={handleDelete}
  title="Delete Image"
  message="Are you sure you want to delete this image?"
  variant="danger"
  confirmButtonText="Delete"
/>

// Type-to-confirm for cascading delete
<ConfirmationModal
  isOpen={isOpen}
  onClose={() => setIsOpen(false)}
  onConfirm={handleDeleteGallery}
  title="Delete Gallery"
  message="This will permanently delete the gallery and all 12 images. This action cannot be undone."
  variant="danger"
  confirmButtonText="Delete Gallery"
  requireConfirmText="DELETE"
/>

// Warning variant
<ConfirmationModal
  isOpen={isOpen}
  onClose={() => setIsOpen(false)}
  onConfirm={handleArchive}
  title="Archive Project"
  message="This project will be moved to archive and won't appear in active projects."
  variant="warning"
  confirmButtonText="Archive"
/>
